/**
 * @param {number[]} robots
 * @param {number[][]} factories
 * @return {number}
 */
var minimumTotalDistance = function(robots, factories) {
    let min = Infinity;

    const dfs = (pos, sum) => {
        if (pos === robots.length) {
            min = Math.min(min, sum);
            return;
        }
        if (sum > min) {
            return;
        }

        for (const factory of factories) {
            if (factory[1] === 0) continue;

            const dist = Math.abs(factory[0] - robots[pos]);
            factory[1]--;
            sum += dist;

            dfs(pos + 1, sum);

            sum -= dist;
            factory[1]++;
        }
    };

    dfs(0, 0);

    return min;
};

