var minimumTotalDistance = function(robot, factory) {
    robot.sort((a, b) => a - b);
    factory.sort((a, b) => a[0] - b[0]);

    const m = robot.length;
    const n = factory.length;

    const dp = Array(m + 1).fill().map(() => Array(n + 1).fill(0));

    for (let i = 0; i < m; i++) {
        dp[i][n] = Infinity;
    }

    for (let j = n - 1; j >= 0; j--) {
        let prefix = 0;
        const qq = [[m, 0]];

        for (let i = m - 1; i >= 0; i--) {
            prefix += Math.abs(robot[i] - factory[j][0]);

            if (qq[0][0] > i + factory[j][1]) {
                qq.shift();
            }

            while (qq.length && qq[qq.length - 1][1] >= dp[i][j + 1] - prefix) {
                qq.pop();
            }

            qq.push([i, dp[i][j + 1] - prefix]);
            dp[i][j] = qq[0][1] + prefix;
        }
    }

    return dp[0][0];
};

/**
 * @param {number[]} robots
 * @param {number[][]} factories
 * @return {number}
 */
var minimumTotalDistance = function(robots, factories) {
    robots.sort((a, b) => a - b);
    factories.sort((a, b) => a[0] - b[0]);

    const factoryPositions = [];
    for (const [pos, rep] of factories) {
        for (let i = 0; i < rep; i++) {
            factoryPositions.push(pos);
        }
    }

    let robotCount = robots.length;
    let factoryCount = factoryPositions.length;
    let next = new Array(factoryCount + 1).fill(0);
    let current = new Array(factoryCount + 1).fill(0);

    current[factoryCount] = Infinity;

    for (let i = robotCount - 1; i >= 0; i--) {
        for (let j = factoryCount - 1; j >= 0; j--) {
            current[j] = Math.min(
                current[j + 1],
                Math.abs(robots[i] - factoryPositions[j]) + next[j + 1],
            );
        }

        next = current.slice(0, factoryCount + 1);
    }

    return current[0];
};
